  const setUser = (u) => {
    setUserState(u);
    localStorage.setItem("hs-user", JSON.stringify(u));
  };

  const login = (email, password) => {
    const found = users.find((u) => u.email === email.trim().toLowerCase());
    if (!found || found.status !== "Active" || password !== DEMO_PASSWORD) return false;
    setUser(found);
