import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { liveBoard, worksites } from "../../data/mock";
import { nowTime } from "../../validate";
import PageTitle from "../../components/PageTitle";
import Banner from "../../components/Banner";
import Badge from "../../components/Badge";
import Modal from "../../components/Modal";
import Field from "../../components/Field";

// FR-SV5 monitor worker check-ins for today
export default function LiveBoard() {
  const navigate = useNavigate();
  const [rows, setRows] = useState(liveBoard);
  const [siteId, setSiteId] = useState("B");
  const [updated, setUpdated] = useState("10:02");
  const [selected, setSelected] = useState(null);
  const [message, setMessage] = useState("");

  const shown = rows.filter((r) => r.siteId === siteId);

  // Late workers 30+ minutes after start become Missed and the supervisor is notified
  const refresh = () => {
    const late = rows.filter((r) => r.state === "Late");
    setRows(rows.map((r) => (r.state === "Late" ? { ...r, state: "Missed" } : r)));
    setUpdated(nowTime());
    setMessage(late.length ? `${late.map((r) => r.worker).join(", ")} marked Missed (not checked in 30 min after start). Supervisor notified.` : "Board refreshed, no changes.");
  };

  return (
    <div>
      <PageTitle title="Live Board" />
      {message && <Banner type={message.includes("Missed") ? "warning" : "success"}>{message}</Banner>}

      <div className="row" style={{ alignItems: "center" }}>
        <Field label="Worksite">
          <select value={siteId} onChange={(e) => setSiteId(e.target.value)}>
            {worksites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </Field>
        <p className="big" style={{ fontWeight: 400, fontSize: "1.2rem" }}>Today / Updated {updated} / {shown.length} assignments</p>
      </div>

      <div className="table-wrap">
        <table className="table">
          <thead>
            <tr><th>Worker</th><th>Task</th><th>State</th><th>Event</th></tr>
          </thead>
          <tbody>
            {shown.map((r) => (
              <tr key={r.id} className="clickable" onClick={() => setSelected(r)}>
                <td>{r.worker}</td>
                <td>{r.task}</td>
                <td><Badge kind={r.state} /></td>
                <td>{r.event}{r.flags.length > 0 && <> / <strong>{r.flags.join(", ")}</strong></>}</td>
              </tr>
            ))}
            {shown.length === 0 && <tr><td colSpan="4">No assignments at this worksite today.</td></tr>}
          </tbody>
        </table>
      </div>
      <p className="hint">Click a worker to see check-in time, breaks and flags.</p>

      <div className="actions">
        <button className="btn" onClick={refresh}>Refresh</button>
        <button className="btn" onClick={() => navigate("/dashboard")}>View weather gates</button>
      </div>

      {selected && (
        <Modal title={`Worker details / ${selected.worker}`} onClose={() => setSelected(null)}>
          <p><strong>Task:</strong> {selected.task} (starts {selected.start})</p>
          <p><strong>State:</strong> <Badge kind={selected.state} /></p>
          <p><strong>Check-in time:</strong> {selected.checkIn || "Not checked in"}</p>
          <p><strong>Breaks:</strong> {selected.breaks.length ? selected.breaks.join(", ") : "None"}</p>
          <p><strong>Flags:</strong> {selected.flags.length ? selected.flags.join(", ") : "None"}</p>
          {selected.flags.includes("Outside radius") && <Banner type="warning">Check-in location was outside the worksite radius. Confirm the reason with the worker.</Banner>}
          <div className="actions">
            <button className="btn btn-primary" onClick={() => setSelected(null)}>Close</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { incidents, worksites } from "../../data/mock";
import PageTitle from "../../components/PageTitle";
import Banner from "../../components/Banner";
import Badge from "../../components/Badge";
import Field from "../../components/Field";

const siteName = (id) => worksites.find((s) => s.id === id)?.name || id;
const dates = [...new Set(incidents.map((i) => i.date))];
const allFilters = { site: "All", status: "All", date: "All" };

// FR-SV6 follow up incidents with filters and a required action note
export default function Incidents() {
  const navigate = useNavigate();
  const [list, setList] = useState(incidents);
  const [draft, setDraft] = useState(allFilters);
  const [filters, setFilters] = useState(allFilters);
  const [selectedId, setSelectedId] = useState(incidents[0].id);
  const [note, setNote] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  const shown = list.filter(
    (i) => (filters.site === "All" || i.siteId === filters.site) && (filters.status === "All" || i.status === filters.status) && (filters.date === "All" || i.date === filters.date)
  );
  const inc = list.find((i) => i.id === selectedId);

  const setD = (e) => setDraft({ ...draft, [e.target.name]: e.target.value });
  const update = (changes) => setList(list.map((i) => (i.id === inc.id ? { ...i, ...changes } : i)));
  const select = (id) => { setSelectedId(id); setNote(""); setError(""); setMessage(""); };

  const startReview = () => { update({ status: "In review" }); setMessage(`${inc.id} is now in review`); };

  // Resolving needs a 10-1000 character action note
  const resolve = () => {
    const text = note.trim();
    if (text.length < 10 || text.length > 1000) return setError("Enter the action taken (10-1000 characters) before resolving.");
    update({ status: "Resolved", note: text });
    setError("");
    setNote("");
    setMessage(`${inc.id} resolved`);
  };

  return (
    <div>
      <PageTitle title="Incidents and follow-up" />
      <div className="row" style={{ alignItems: "flex-end" }}>
        <Field label="Site">
          <select name="site" value={draft.site} onChange={setD}>
            <option value="All">All sites</option>
            {worksites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </Field>
        <Field label="Status">
          <select name="status" value={draft.status} onChange={setD}>
            {["All", "Open", "In review", "Resolved"].map((s) => <option key={s}>{s}</option>)}
          </select>
        </Field>
        <Field label="Date">
          <select name="date" value={draft.date} onChange={setD}>
            <option value="All">All dates</option>
            {dates.map((d) => <option key={d}>{d}</option>)}
          </select>
        </Field>
      </div>
      <div className="actions" style={{ marginTop: 0 }}>
        <button className="btn btn-primary" onClick={() => setFilters(draft)}>Apply Filters</button>
        <button className="btn" onClick={() => navigate("/report-incident")}>Report Incident</button>
      </div>

      <div className="table-wrap">
        <table className="table">
          <thead>
            <tr><th>Reference</th><th>Type</th><th>Site</th><th>Reporter</th><th>Status</th></tr>
          </thead>
          <tbody>
            {shown.map((i) => (
              <tr key={i.id} className={`clickable ${i.id === selectedId ? "selected" : ""}`} onClick={() => select(i.id)}>
                <td>{i.id}</td>
                <td>{i.type}</td>
                <td>{siteName(i.siteId)}</td>
                <td>{i.reporter}</td>
                <td><Badge kind={i.status} /></td>
              </tr>
            ))}
            {shown.length === 0 && <tr><td colSpan="5">No incidents match these filters.</td></tr>}
          </tbody>
        </table>
      </div>

      {inc && (
        <div className="card">
          <h2>{inc.id} / {siteName(inc.siteId)} / {inc.date} {inc.time}</h2>
          {message && <Banner type="success">{message}</Banner>}
          <p>{inc.description} Photo: optional, none attached.</p>
          <p>Type: {inc.type} / Task: {inc.taskId || "None"} / Reported by {inc.reporter}</p>
          <p>Weather snapshot: HI {inc.heatIndex} C <Badge kind={inc.level} /> / Status: <Badge kind={inc.status} /></p>

          {inc.status === "Resolved" ? (
            <p><strong>Action taken:</strong> {inc.note}</p>
          ) : (
            <>
              <Field label="Action taken *" error={error} hint="Resolution requires a 10-1000 character action note; history is retained.">
                <textarea value={note} maxLength={1000} onChange={(e) => setNote(e.target.value)} />
              </Field>
              <div className="actions">
                {inc.status === "Open" && <button className="btn" onClick={startReview}>Start Review</button>}
                <button className="btn btn-primary" onClick={resolve}>Resolve</button>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { reportSummary, worksites } from "../../data/mock";
import PageTitle from "../../components/PageTitle";
import Field from "../../components/Field";

// Demo records only exist in this date range
const DATA_FROM = "2026-06-22";
const DATA_TO = "2026-07-10";
const initial = { from: DATA_FROM, to: DATA_TO, site: "All" };

// Line chart drawn with plain SVG
function LineChart({ points }) {
  const max = Math.max(...points.map((p) => p.count), 1);
  const x = (i) => 30 + (i * 240) / Math.max(points.length - 1, 1);
  const y = (c) => 110 - (c / max) * 80;
  return (
    <svg viewBox="0 0 300 140" className="line-chart" role="img" aria-label="Incidents per week">
      <polyline fill="none" stroke="currentColor" strokeWidth="2.5" points={points.map((p, i) => `${x(i)},${y(p.count)}`).join(" ")} />
      {points.map((p, i) => (
        <g key={p.week}>
          <circle cx={x(i)} cy={y(p.count)} r="4" fill="currentColor" />
          <text x={x(i)} y={y(p.count) - 10} textAnchor="middle">{p.count}</text>
          <text x={x(i)} y="134" textAnchor="middle">{p.week}</text>
        </g>
      ))}
    </svg>
  );
}

// FR-SV7 compliance reports with summary cards and two charts
export default function Reports() {
  const navigate = useNavigate();
  const [draft, setDraft] = useState(initial);
  const [filters, setFilters] = useState(initial);
  const [error, setError] = useState("");
  const [forceEmpty, setForceEmpty] = useState(false);

  const setD = (e) => setDraft({ ...draft, [e.target.name]: e.target.value });

  const apply = () => {
    if (!draft.from || !draft.to || draft.from >= draft.to) return setError("Start date must be before end date.");
    setError("");
    setForceEmpty(false);
    setFilters(draft);
  };

  // No overlap with the demo records means nothing to show
  const empty = forceEmpty || filters.to < DATA_FROM || filters.from > DATA_TO;
  const r = reportSummary;
  const maxType = Math.max(...r.byType.map((t) => t.count));
  const siteLabel = filters.site === "All" ? "All authorized sites" : worksites.find((s) => s.id === filters.site).name;

  return (
    <div>
      <PageTitle title="Reports and summaries" />
      <div className="row no-print" style={{ alignItems: "flex-end" }}>
        <Field label="Start date" error={error}>
          <input type="date" name="from" value={draft.from} onChange={setD} />
        </Field>
        <Field label="End date">
          <input type="date" name="to" value={draft.to} onChange={setD} />
        </Field>
        <Field label="Site">
          <select name="site" value={draft.site} onChange={setD}>
            <option value="All">All authorized</option>
            {worksites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </Field>
      </div>
      <div className="actions no-print" style={{ marginTop: 0 }}>
        <button className="btn btn-primary" onClick={apply}>Apply Filters</button>
      </div>

      <p className="hint">Report for {siteLabel} / {filters.from} to {filters.to}</p>

      {empty ? (
        <div className="card muted">
          <h2>No records match these filters</h2>
          <p>Try a wider date range or another site.</p>
        </div>
      ) : (
        <>
          <div className="card-grid stat-grid">
            <div className="card"><h3>Tasks / completed</h3><p className="stat">{r.scheduled} / {r.completed}</p></div>
            <div className="card"><h3>High authorizations</h3><p className="stat">{r.highAuthorizations}</p></div>
            <div className="card"><h3>Checklist rate</h3><p className="stat">{Math.round((r.checklistDone / r.checklistTotal) * 100)}% ({r.checklistDone}/{r.checklistTotal})</p></div>
            <div className="card"><h3>Missed assignments</h3><p className="stat">{r.missed}</p></div>
          </div>

          <div className="card-grid">
            <div className="card">
              <h2>Incidents per week / counts</h2>
              <LineChart points={r.perWeek} />
            </div>
            <div className="card">
              <h2>Incidents by type</h2>
              {r.byType.map((t) => (
                <div className="hbar-row" key={t.type}>
                  <span className="hbar-label">{t.type}</span>
                  <div className="hbar" style={{ width: `${(t.count / maxType) * 60}%` }} />
                  <span>{t.count}</span>
                </div>
              ))}
            </div>
          </div>
        </>
      )}

      <div className="actions no-print">
        <button className="btn" onClick={() => window.print()} disabled={empty}>Print / Save PDF</button>
        <button className="btn" onClick={() => navigate("/incidents")}>Source records</button>
        <button className="btn" onClick={() => setForceEmpty(!forceEmpty)}>{forceEmpty ? "Show results" : "Empty results"}</button>
      </div>
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "../../AuthContext";
import { roleLabels, users } from "../../data/mock";
import { isEmail, isStrongPassword, PASSWORD_HINT } from "../../validate";
import PageTitle from "../../components/PageTitle";
